/**
 * HudRenderer.js
 * ---------------------------------------------------------------
 * HUD Canvas: solo la flecha de entrega (§4).
 *
 * El HUD informativo (nivel, tiempo, canasta, leyenda, pausa)
 * se migró a HTML/CSS (GameHud.jsx) en el Block 1.
 *
 * Elementos del mundo (jugador, supervisor, canasta, camión,
 * partículas) NO se dibujan aquí. Se encargan Renderer.js.
 */

import { SpriteRenderer } from './SpriteRenderer.js';

/* ============================================================
   HUD RENDERER (versión mínima post-migración HTML)
   ============================================================ */
export class HudRenderer {
  /**
   * @param {import('./SpriteRenderer.js').SpriteRenderer} sprites
   */
  constructor(sprites) {
    this.sprites = sprites;
    /** Alto lógico de la ventana; lo fija GameEngine. */
    this.width = 480;
    this.height = 800;
    this.hudHeight = 0;
    this.bottomHeight = 0;
  }

  /** Ajusta las dimensiones lógicas. No-op post-migración. */
  resize() {}

  /* ===========================================================
     INDICADOR "ENTREGAR" (§4)
     ============================================================ */

  /** Flecha verde que señala la canasta cuando se puede entregar. */
  drawDeliverArrow(x, y, t = 0) {
    const bob = Math.round(Math.sin(t) * 2);

    this.sprites.ctx.save();
    this.sprites.ctx.globalAlpha = 0.95;
    this.sprites.draw('ui.promptsDeliverArrow', x, y + bob, {
      frameSize: 24,
      width: 22,
      height: 22,
    });
    this.sprites.ctx.restore();
  }
}

export { };
export default HudRenderer;